import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  normalizeKey,
  notify,
  pad,
  resolveWorkspace,
  timeAgo,
  truncate,
} from "./shared.js";

type KanbanCard = {
  id: string;
  title: string;
  status?: string;
  storyCount?: number;
  model?: string | null;
  createdAt?: string;
  created_at?: string;
  activeRunStatus?: string | null;
  queuePosition?: number | null;
  userStories?: unknown[];
};

type KanbanResponse = {
  columns?: Array<{ id?: string; title?: string; specs?: KanbanCard[]; items?: KanbanCard[] }>;
  items?: KanbanCard[];
};

type BoardColumn = {
  key: "draft" | "in_progress" | "done";
  title: string;
  cards: KanbanCard[];
};

function getCardsFromResponse(payload: KanbanResponse): KanbanCard[] {
  if (Array.isArray(payload.columns)) {
    return payload.columns.flatMap((column) => column.specs ?? column.items ?? []);
  }
  return payload.items ?? [];
}

function toColumns(cards: KanbanCard[]): BoardColumn[] {
  const columns: BoardColumn[] = [
    { key: "draft", title: "DRAFT", cards: [] },
    { key: "in_progress", title: "IN PROGRESS", cards: [] },
    { key: "done", title: "DONE", cards: [] },
  ];

  for (const card of cards) {
    if (card.activeRunStatus === "running" || card.activeRunStatus === "queued") {
      columns[1].cards.push(card);
    } else if (card.status === "passed" || card.status === "done" || card.status === "completed") {
      columns[2].cards.push(card);
    } else {
      columns[0].cards.push(card);
    }
  }

  return columns;
}

function clampIndexes(columns: BoardColumn[], columnIndex: number, rowIndex: number) {
  const safeColumnIndex = Math.max(0, Math.min(columnIndex, columns.length - 1));
  const maxRow = Math.max(0, (columns[safeColumnIndex]?.cards.length ?? 1) - 1);
  return {
    columnIndex: safeColumnIndex,
    rowIndex: Math.max(0, Math.min(rowIndex, maxRow)),
  };
}

function renderColumns(columns: BoardColumn[], columnIndex: number, rowIndex: number, width: number): string[] {
  const totalWidth = Math.max(90, width);
  const columnWidth = Math.max(24, Math.floor((totalWidth - 6) / 3));
  const heights = columns.map((column) => Math.max(4, column.cards.length + 2));
  const maxHeight = Math.max(...heights);

  const rendered = columns.map((column, idx) => {
    const lines: string[] = [];
    lines.push(pad(`[${column.title}]`, columnWidth));

    if (column.cards.length === 0) {
      lines.push(pad("No specs in this column.", columnWidth));
    } else {
      column.cards.forEach((card, cardIdx) => {
        const focused = idx === columnIndex && cardIdx === rowIndex;
        const label = `${truncate(card.title, 28)} | ${card.storyCount ?? card.userStories?.length ?? 0} stories | ${card.model || "auto"} | ${timeAgo(card.createdAt ?? card.created_at)}`;
        const padded = pad(truncate(label, columnWidth), columnWidth);
        lines.push(focused ? `\x1b[7m${padded}\x1b[0m` : padded);
      });
    }

    while (lines.length < maxHeight) {
      lines.push(" ".repeat(columnWidth));
    }

    return lines;
  });

  const out: string[] = [];
  for (let row = 0; row < maxHeight; row += 1) {
    out.push(`${rendered[0]?.[row] ?? ""} │ ${rendered[1]?.[row] ?? ""} │ ${rendered[2]?.[row] ?? ""}`);
  }
  return out;
}

export async function openSpecBoard(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  baseUrl: string,
  token?: string,
): Promise<void> {
  const workspace = await resolveWorkspace(baseUrl, token);

  if (!ctx.ui.custom) {
    notify(ctx.ui, "Pi custom UI is unavailable in this session. Use /rorca-tui as fallback.", "warning");
    return;
  }

  await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
    let columns: BoardColumn[] = toColumns([]);
    let columnIndex = 0;
    let rowIndex = 0;
    let busy = true;
    let statusLine = "Loading specs…";
    let mounted = true;
    let refreshTimer: NodeJS.Timeout | undefined;

    const currentCard = () => columns[columnIndex]?.cards[rowIndex];

    const requestRender = () => {
      if (mounted) {
        tui.requestRender();
      }
    };

    const refresh = async () => {
      const payload = await apiFetchJson<KanbanResponse>(
        baseUrl,
        `/api/specs/kanban?workspaceId=${encodeURIComponent(workspace.id)}`,
        { token },
      );
      columns = toColumns(getCardsFromResponse(payload));
      const clamped = clampIndexes(columns, columnIndex, rowIndex);
      columnIndex = clamped.columnIndex;
      rowIndex = clamped.rowIndex;
      statusLine = `Workspace ${workspace.label} • ${columns.reduce((sum, column) => sum + column.cards.length, 0)} specs`;
    };

    const runAction = (action: () => Promise<void>) => {
      if (busy) {
        return;
      }
      busy = true;
      statusLine = "Working…";
      requestRender();

      void (async () => {
        try {
          await action();
          await refresh();
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          statusLine = `Error: ${message}`;
          notify(ctx.ui, message, "error");
        } finally {
          busy = false;
          requestRender();
        }
      })();
    };

    const startRefreshTimer = () => {
      if (refreshTimer) {
        clearInterval(refreshTimer);
      }
      refreshTimer = setInterval(() => {
        void refresh().then(requestRender).catch((error) => {
          const message = error instanceof Error ? error.message : String(error);
          statusLine = `Refresh failed: ${message}`;
          requestRender();
        });
      }, 30_000);
    };

    void (async () => {
      try {
        await refresh();
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        statusLine = `Failed to load board: ${message}`;
        notify(ctx.ui, message, "error");
      } finally {
        busy = false;
        startRefreshTimer();
        requestRender();
      }
    })();

    return {
      handleInput(data: string) {
        const key = normalizeKey(data);

        if (key === "q" || key === "escape" || key === "ctrl+c") {
          mounted = false;
          if (refreshTimer) {
            clearInterval(refreshTimer);
          }
          done();
          return;
        }

        if (busy) {
          return;
        }

        if (key === "down" || key === "j") {
          rowIndex = Math.min(rowIndex + 1, Math.max(0, columns[columnIndex]?.cards.length - 1));
          requestRender();
          return;
        }

        if (key === "up" || key === "k") {
          rowIndex = Math.max(0, rowIndex - 1);
          requestRender();
          return;
        }

        if (key === "left" || key === "h") {
          const clamped = clampIndexes(columns, (columnIndex + columns.length - 1) % columns.length, rowIndex);
          columnIndex = clamped.columnIndex;
          rowIndex = clamped.rowIndex;
          requestRender();
          return;
        }

        if (key === "right" || key === "l" || key === "tab") {
          const clamped = clampIndexes(columns, (columnIndex + 1) % columns.length, rowIndex);
          columnIndex = clamped.columnIndex;
          rowIndex = clamped.rowIndex;
          requestRender();
          return;
        }

        if (key === "r") {
          runAction(async () => {
            startRefreshTimer();
            await refresh();
            statusLine = `Workspace ${workspace.label} • refreshed`;
          });
          return;
        }

        if (key === "a") {
          const card = currentCard();
          if (!card) {
            return;
          }
          runAction(async () => {
            await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(card.id)}/approve`, {
              method: "POST",
              token,
              body: { workspaceId: workspace.id },
            });
            statusLine = `Approved ${card.title}`;
            notify(ctx.ui, `Approved ${card.title}`, "success");
          });
          return;
        }

        if (key === "x") {
          const card = currentCard();
          if (!card) {
            return;
          }
          runAction(async () => {
            const ok = (await ctx.ui.confirm?.("Reject spec", `Reject ${card.title}?`)) ?? false;
            if (!ok) {
              statusLine = `Reject cancelled for ${card.title}`;
              return;
            }
            await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(card.id)}/reject`, {
              method: "POST",
              token,
              body: { workspaceId: workspace.id, reason: "Rejected from Pi board" },
            });
            statusLine = `Rejected ${card.title}`;
            notify(ctx.ui, `Rejected ${card.title}`, "warning");
          });
          return;
        }

        if (key === "enter") {
          const card = currentCard();
          if (card) {
            statusLine = `Selected ${card.id}. Detail view is still being migrated; use /rorca-tui for full-screen detail.`;
            notify(ctx.ui, `Selected ${card.id}. Use /rorca-tui for full-screen detail view.`, "info");
            requestRender();
          }
        }
      },

      render(width: number): string[] {
        const lines: string[] = [];
        lines.push(`Rorca Spec Board — ${workspace.label}`);
        lines.push("");
        lines.push(...renderColumns(columns, columnIndex, rowIndex, width));
        lines.push("");
        lines.push(truncate(statusLine, Math.max(20, width)));
        lines.push(truncate("j/k or ↑/↓ move • h/l or ←/→ change column • a approve • x reject • r refresh • q quit", Math.max(20, width)));
        return lines;
      },

      invalidate() {
        // Stateless renderer
      },
    };
  });
}

import { preflight, resolveStoryModel } from "../lib/preflight.js";
import { openRunView } from "./run-view.js";
import {
  type ExtensionAPI,
  apiFetchJson,
  clearScreen,
  confirm,
  normalizeKey,
  notify,
  resolveWorkspace,
  timeAgo,
  truncate,
} from "./shared.js";

type Story = {
  id: string;
  title: string;
  description?: string;
  acceptanceCriteria?: string[];
  model?: string;
};

type SpecPayload = {
  id: string;
  title?: string;
  model?: string;
  userStories?: Story[];
};

type RunSummary = {
  id: string;
  spec_path?: string;
  status: string;
  started_at?: string;
};

type RunDetail = {
  run: { id: string; status: string; spec_path?: string; agent_model?: string | null };
  stories?: Array<{ story_id: string; status: string }>;
};

function iconForStatus(status: string | undefined): string {
  switch (status) {
    case "pass":
    case "passed":
      return "✓";
    case "fail":
    case "failed":
      return "✗";
    case "running":
      return "↺";
    case "skip":
    case "skipped":
      return "—";
    default:
      return "○";
  }
}

export async function openSpecDetail(pi: ExtensionAPI, specId: string, baseUrl: string, token?: string): Promise<void> {
  const workspace = await resolveWorkspace(baseUrl, token);
  let spec: SpecPayload = await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(specId)}?workspaceId=${encodeURIComponent(workspace.id)}`, { token });
  let runsPayload = await apiFetchJson<{ items?: RunSummary[] }>(baseUrl, `/api/pipeline/runs?workspaceId=${encodeURIComponent(workspace.id)}`, { token });
  let runs = (runsPayload.items ?? []).filter((item) => item.spec_path?.endsWith(`${specId}.json`));
  let latestRun = runs[0];
  let runDetail: RunDetail | null = latestRun ? await apiFetchJson(baseUrl, `/api/pipeline/runs/${latestRun.id}`, { token }) : null;
  let storyIndex = 0;
  let actionIndex = 0;
  let focus: "stories" | "actions" = "stories";
  const actions = ["Run", "Retry Failed", "History"];

  const statusMap = new Map((runDetail?.stories ?? []).map((story) => [story.story_id, story.status]));

  const refresh = async () => {
    spec = await apiFetchJson(baseUrl, `/api/specs/${encodeURIComponent(specId)}?workspaceId=${encodeURIComponent(workspace.id)}`, { token });
    runsPayload = await apiFetchJson(baseUrl, `/api/pipeline/runs?workspaceId=${encodeURIComponent(workspace.id)}`, { token });
    runs = (runsPayload.items ?? []).filter((item: RunSummary) => item.spec_path?.endsWith(`${specId}.json`));
    latestRun = runs[0];
    runDetail = latestRun ? await apiFetchJson(baseUrl, `/api/pipeline/runs/${latestRun.id}`, { token }) : null;
    statusMap.clear();
    for (const story of runDetail?.stories ?? []) {
      statusMap.set(story.story_id, story.status);
    }
  };

  const render = () => {
    clearScreen();
    process.stdout.write(`${spec.title || spec.id}\n`);
    process.stdout.write(`Workspace: ${workspace.label} | Model: ${spec.model || "auto"} | Latest run: ${latestRun ? `${latestRun.id} (${latestRun.status})` : "none"}\n\n`);

    const stories = spec.userStories ?? [];
    stories.forEach((story, index) => {
      const focused = focus === "stories" && index === storyIndex;
      const line = `${iconForStatus(statusMap.get(story.id))} ${story.id}: ${truncate(story.title, 55)}`;
      process.stdout.write(`${focused ? `\x1b[7m${line}\x1b[0m` : line}\n`);
      if (focused) {
        for (const [criteriaIndex, criteria] of (story.acceptanceCriteria ?? []).slice(0, 10).entries()) {
          process.stdout.write(`    ${criteriaIndex + 1}. ${truncate(criteria, 100)}\n`);
        }
      }
    });

    process.stdout.write("\n");
    process.stdout.write(actions.map((action, index) => {
      const focusedAction = focus === "actions" && index === actionIndex;
      return focusedAction ? `\x1b[7m[${action}]\x1b[0m` : `[${action}]`;
    }).join(" "));
    process.stdout.write("\n\nTAB: switch focus  Enter: activate  q: back\n");
  };

  const runSpec = async () => {
    const result = await preflight({
      specId,
      workspaceId: workspace.id,
      workspacePath: workspace.path,
      baseUrl,
      token,
    });

    if (!result.ok) {
      throw new Error(`Preflight failed:\n${result.errors.join("\n")}`);
    }

    if (result.warnings.length > 0) {
      const proceed = await confirm(`Proceed despite warnings? ${result.warnings.join(" | ")} (y/N)`);
      if (!proceed) {
        return;
      }
    }

    const story = (spec.userStories ?? [])[storyIndex] ?? {};
    const model = resolveStoryModel(story, { model: spec.model });
    const payload = await apiFetchJson<{ ok: boolean; runId?: string; run_id?: string; conflict?: boolean; activeRunId?: string }>(
      baseUrl,
      "/api/pipeline/trigger",
      {
        method: "POST",
        token,
        body: {
          specPath: `forge/specs/approved/${specId}.json`,
          workspaceId: workspace.id,
          autoWorktree: true,
          includeGraph: true,
          agentType: "codex",
          model,
        },
      },
    );

    const runId = Number(payload.runId ?? payload.run_id ?? payload.activeRunId);
    if (Number.isFinite(runId) && runId > 0) {
      await openRunView(pi, runId, baseUrl, token);
    }
  };

  const retryFailed = async () => {
    if (!latestRun) {
      throw new Error("No run history for this spec");
    }
    const failedStoryIds = (runDetail?.stories ?? []).filter((story) => story.status === "failed" || story.status === "fail").map((story) => story.story_id);
    if (failedStoryIds.length === 0) {
      notify(undefined, "No failed stories to retry", "info");
      return;
    }
    await apiFetchJson(baseUrl, `/api/pipeline/runs/${latestRun.id}/retry`, {
      method: "POST",
      token,
      body: { storyIds: failedStoryIds },
    });
    await refresh();
  };

  const showHistory = async () => {
    clearScreen();
    process.stdout.write(`Last runs for ${specId}\n\n`);
    for (const run of runs.slice(0, 5)) {
      process.stdout.write(`${run.id}: ${run.status} | ${timeAgo(run.started_at)}\n`);
    }
    process.stdout.write("\nPress Enter to return...");
    await new Promise<void>((resolve) => {
      const onData = (chunk: Buffer) => {
        const key = normalizeKey(chunk);
        if (key === "enter" || key === "escape" || key === "q" || key === "ctrl+c") {
          process.stdin.off("data", onData);
          resolve();
        }
      };
      process.stdin.on("data", onData);
    });
  };

  render();

  await new Promise<void>((resolve) => {
    const cleanup = () => {
      process.stdin.off("data", onData);
      if (process.stdin.isTTY && typeof process.stdin.setRawMode === "function") {
        process.stdin.setRawMode(false);
      }
      process.stdin.pause();
      clearScreen();
    };

    const onData = async (chunk: Buffer) => {
      const key = normalizeKey(chunk);
      try {
        if (key === "q" || key === "escape" || key === "ctrl+c") {
          cleanup();
          resolve();
          return;
        }
        if (key === "tab") {
          focus = focus === "stories" ? "actions" : "stories";
        } else if (focus === "stories" && (key === "down" || key === "j")) {
          storyIndex = Math.min(storyIndex + 1, Math.max(0, (spec.userStories ?? []).length - 1));
        } else if (focus === "stories" && (key === "up" || key === "k")) {
          storyIndex = Math.max(0, storyIndex - 1);
        } else if (focus === "actions" && (key === "left" || key === "h")) {
          actionIndex = (actionIndex + actions.length - 1) % actions.length;
        } else if (focus === "actions" && (key === "right" || key === "l")) {
          actionIndex = (actionIndex + 1) % actions.length;
        } else if (key === "enter" && focus === "actions") {
          if (actionIndex === 0) {
            await runSpec();
            await refresh();
          } else if (actionIndex === 1) {
            await retryFailed();
          } else {
            await showHistory();
          }
        }
      } catch (error) {
        notify(undefined, error instanceof Error ? error.message : String(error), "error");
      }
      render();
    };

    if (process.stdin.isTTY && typeof process.stdin.setRawMode === "function") {
      process.stdin.setRawMode(true);
    }
    process.stdin.resume();
    process.stdin.on("data", onData);
  });
}

/**
 * Overlay Test - validates overlay compositing with inline text inputs
 *
 * Usage: pi --extension ./examples/extensions/overlay-test.ts
 *
 * Run /overlay-test to show a floating overlay with:
 * - Inline text inputs within menu items
 * - Edge case tests (wide chars, styled text, emoji)
 */

import type { ExtensionAPI, ExtensionCommandContext, Theme } from "@mariozechner/pi-coding-agent";
import { CURSOR_MARKER, type Focusable, matchesKey, visibleWidth } from "@mariozechner/pi-tui";

export default function (pi: ExtensionAPI) {
	pi.registerCommand("overlay-test", {
		description: "Test overlay rendering with edge cases",
		handler: async (_args: string, ctx: ExtensionCommandContext) => {
			const result = await ctx.ui.custom<{ action: string; query?: string } | undefined>(
				(_tui, theme, _keybindings, done) => new OverlayTestComponent(theme, done),
				{ overlay: true },
			);

			if (result) {
				const msg = result.query ? `${result.action}: "${result.query}"` : result.action;
				ctx.ui.notify(msg, "info");
			}
		},
	});
}

class OverlayTestComponent implements Focusable {
	readonly width = 70;

	/** Focusable interface - set by TUI when focus changes */
	focused = false;

	private selected = 0;
	private items = [
		{ label: "Search", hasInput: true, text: "", cursor: 0 },
		{ label: "Run", hasInput: true, text: "", cursor: 0 },
		{ label: "Settings", hasInput: false, text: "", cursor: 0 },
		{ label: "Cancel", hasInput: false, text: "", cursor: 0 },
	];

	constructor(
		private theme: Theme,
		private done: (result: { action: string; query?: string } | undefined) => void,
	) {}

	handleInput(data: string): void {
		if (matchesKey(data, "escape")) {
			this.done(undefined);
			return;
		}

		const current = this.items[this.selected]!;

		if (matchesKey(data, "return")) {
			this.done({ action: current.label, query: current.hasInput ? current.text : undefined });
			return;
		}

		if (matchesKey(data, "up")) {
			this.selected = Math.max(0, this.selected - 1);
		} else if (matchesKey(data, "down")) {
			this.selected = Math.min(this.items.length - 1, this.selected + 1);
		} else if (current.hasInput) {
			if (matchesKey(data, "backspace")) {
				if (current.cursor > 0) {
					current.text = current.text.slice(0, current.cursor - 1) + current.text.slice(current.cursor);
					current.cursor--;
				}
			} else if (matchesKey(data, "left")) {
				current.cursor = Math.max(0, current.cursor - 1);
			} else if (matchesKey(data, "right")) {
				current.cursor = Math.min(current.text.length, current.cursor + 1);
			} else if (data.length === 1 && data.charCodeAt(0) >= 32) {
				current.text = current.text.slice(0, current.cursor) + data + current.text.slice(current.cursor);
				current.cursor++;
			}
		}
	}

	render(_width: number): string[] {
		const w = this.width;
		const th = this.theme;
		const innerW = w - 2;
		const lines: string[] = [];

		const pad = (s: string, len: number) => {
			const vis = visibleWidth(s);
			return s + " ".repeat(Math.max(0, len - vis));
		};

		const row = (content: string) => th.fg("border", "│") + pad(content, innerW) + th.fg("border", "│");

		lines.push(th.fg("border", `╭${"─".repeat(innerW)}╮`));
		lines.push(row(` ${th.fg("accent", "🧪 Overlay Test")}`));
		lines.push(row(""));

		// Edge cases - full width lines to test compositing at boundaries
		lines.push(row(` ${th.fg("dim", "─── Edge Cases (borders should align) ───")}`));
		lines.push(row(` Wide: ${th.fg("warning", "中文日本語한글テスト漢字繁體简体ひらがなカタカナ가나다라마바")}`));
		lines.push(
			row(
				` Styled: ${th.fg("error", "RED")} ${th.fg("success", "GREEN")} ${th.fg("warning", "YELLOW")} ${th.fg("accent", "ACCENT")} ${th.fg("dim", "DIM")} ${th.fg("error", "more")} ${th.fg("success", "colors")}`,
			),
		);
		lines.push(row(" Emoji: 👨‍👩‍👧‍👦 🇯🇵 🚀 💻 🎉 🔥 😀 🎯 🌟 💡 🎨 🔧 📦 🏆 🌈 🎪 🎭 🎬 🎮 🎲"));
		lines.push(row(""));

		// Menu with inline inputs
		lines.push(row(` ${th.fg("dim", "─── Actions ───")}`));

		for (let i = 0; i < this.items.length; i++) {
			const item = this.items[i]!;
			const isSelected = i === this.selected;
			const prefix = isSelected ? " ▶ " : "   ";

			let content: string;
			if (item.hasInput) {
				const label = isSelected ? th.fg("accent", `${item.label}:`) : th.fg("text", `${item.label}:`);

				let inputDisplay = item.text;
				if (isSelected) {
					const before = inputDisplay.slice(0, item.cursor);
					const cursorChar = item.cursor < inputDisplay.length ? inputDisplay[item.cursor] : " ";
					const after = inputDisplay.slice(item.cursor + 1);
					// Emit hardware cursor marker for IME support when focused
					const marker = this.focused ? CURSOR_MARKER : "";
					inputDisplay = `${before}${marker}\x1b[7m${cursorChar}\x1b[27m${after}`;
				}
				content = `${prefix + label} ${inputDisplay}`;
			} else {
				content = prefix + (isSelected ? th.fg("accent", item.label) : th.fg("text", item.label));
			}

			lines.push(row(content));
		}

		lines.push(row(""));
		lines.push(row(` ${th.fg("dim", "↑↓ navigate • type to input • Enter select • Esc cancel")}`));
		lines.push(th.fg("border", `╰${"─".repeat(innerW)}╯`));

		return lines;
	}

	invalidate(): void {}
	dispose(): void {}
}

/**
 * Custom Footer Extension - demonstrates ctx.ui.setFooter()
 *
 * footerData exposes data not otherwise accessible:
 * - getGitBranch(): current git branch
 * - getExtensionStatuses(): texts from ctx.ui.setStatus()
 *
 * Token stats come from ctx.sessionManager/ctx.model (already accessible).
 */

import type { AssistantMessage } from "@mariozechner/pi-ai";
import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { truncateToWidth, visibleWidth } from "@mariozechner/pi-tui";

export default function (pi: ExtensionAPI) {
	let enabled = false;

	pi.registerCommand("footer", {
		description: "Toggle custom footer",
		handler: async (_args, ctx) => {
			enabled = !enabled;

			if (enabled) {
				ctx.ui.setFooter((tui, theme, footerData) => {
					const unsub = footerData.onBranchChange(() => tui.requestRender());

					return {
						dispose: unsub,
						invalidate() {},
						render(width: number): string[] {
							// Compute tokens from ctx (already accessible to extensions)
							let input = 0,
								output = 0,
								cost = 0;
							for (const e of ctx.sessionManager.getBranch()) {
								if (e.type === "message" && e.message.role === "assistant") {
									const m = e.message as AssistantMessage;
									input += m.usage.input;
									output += m.usage.output;
									cost += m.usage.cost.total;
								}
							}

							// Get git branch (not otherwise accessible)
							const branch = footerData.getGitBranch();
							const fmt = (n: number) => (n < 1000 ? `${n}` : `${(n / 1000).toFixed(1)}k`);

							const left = theme.fg("dim", `↑${fmt(input)} ↓${fmt(output)} $${cost.toFixed(3)}`);
							const branchStr = branch ? ` (${branch})` : "";
							const right = theme.fg("dim", `${ctx.model?.id || "no-model"}${branchStr}`);

							const pad = " ".repeat(Math.max(1, width - visibleWidth(left) - visibleWidth(right)));
							return [truncateToWidth(left + pad + right, width)];
						},
					};
				});
				ctx.ui.notify("Custom footer enabled", "info");
			} else {
				ctx.ui.setFooter(undefined);
				ctx.ui.notify("Default footer restored", "info");
			}
		},
	});
}

/**
 * Preset Extension
 *
 * Allows defining named presets that configure model, thinking level, tools,
 * and system prompt instructions. Presets are defined in JSON config files
 * and can be activated via CLI flag, /preset command, or Ctrl+Shift+U to cycle.
 *
 * Config files (merged, project takes precedence):
 * - ~/.pi/agent/presets.json (global)
 * - <cwd>/.pi/presets.json (project-local)
 *
 * Example presets.json:
 * ```json
 * {
 *   "plan": {
 *     "provider": "openai-codex",
 *     "model": "gpt-5.2-codex",
 *     "thinkingLevel": "high",
 *     "tools": ["read", "grep", "find", "ls"],
 *     "instructions": "You are in PLANNING MODE. Your job is to deeply understand the problem and create a detailed implementation plan.\n\nRules:\n- DO NOT make any changes. You cannot edit or write files.\n- Read files IN FULL (no offset/limit) to get complete context. Partial reads miss critical details.\n- Explore thoroughly: grep for related code, find similar patterns, understand the architecture.\n- Ask clarifying questions if requirements are ambiguous. Do not assume.\n- Identify risks, edge cases, and dependencies before proposing solutions.\n\nOutput:\n- Create a structured plan with numbered steps.\n- For each step: what to change, why, and potential risks.\n- List files that will be modified.\n- Note any tests that should be added or updated.\n\nWhen done, ask the user if they want you to:\n1. Write the plan to a markdown file (e.g., PLAN.md)\n2. Create a GitHub issue with the plan\n3. Proceed to implementation (they should switch to 'implement' preset)"
 *   },
 *   "implement": {
 *     "provider": "anthropic",
 *     "model": "claude-sonnet-4-5",
 *     "thinkingLevel": "high",
 *     "tools": ["read", "bash", "edit", "write"],
 *     "instructions": "You are in IMPLEMENTATION MODE. Your job is to make focused, correct changes.\n\nRules:\n- Keep scope tight. Do exactly what was asked, no more.\n- Read files before editing to understand current state.\n- Make surgical edits. Prefer edit over write for existing files.\n- Explain your reasoning briefly before each change.\n- Run tests or type checks after changes if the project has them (npm test, npm run check, etc.).\n- If you encounter unexpected complexity, STOP and explain the issue rather than hacking around it.\n\nIf no plan exists:\n- Ask clarifying questions before starting.\n- Propose what you'll do and get confirmation for non-trivial changes.\n\nAfter completing changes:\n- Summarize what was done.\n- Note any follow-up work or tests that should be added."
 *   }
 * }
 * ```
 *
 * Usage:
 * - `pi --preset plan` - start with plan preset
 * - `/preset` - show selector to switch presets mid-session
 * - `/preset implement` - switch to implement preset directly
 * - `Ctrl+Shift+U` - cycle through presets
 *
 * CLI flags always override preset values.
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { ExtensionAPI, ExtensionContext } from "@mariozechner/pi-coding-agent";
import { DynamicBorder, getAgentDir } from "@mariozechner/pi-coding-agent";
import { Container, Key, type SelectItem, SelectList, Text } from "@mariozechner/pi-tui";

// Preset configuration
interface Preset {
	/** Provider name (e.g., "anthropic", "openai") */
	provider?: string;
	/** Model ID (e.g., "claude-sonnet-4-5") */
	model?: string;
	/** Thinking level */
	thinkingLevel?: "off" | "minimal" | "low" | "medium" | "high" | "xhigh";
	/** Tools to enable (replaces default set) */
	tools?: string[];
	/** Instructions to append to system prompt */
	instructions?: string;
}

interface PresetsConfig {
	[name: string]: Preset;
}

/**
 * Load presets from config files.
 * Project-local presets override global presets with the same name.
 */
function loadPresets(cwd: string): PresetsConfig {
	const globalPath = join(getAgentDir(), "presets.json");
	const projectPath = join(cwd, ".pi", "presets.json");

	let globalPresets: PresetsConfig = {};
	let projectPresets: PresetsConfig = {};

	// Load global presets
	if (existsSync(globalPath)) {
		try {
			const content = readFileSync(globalPath, "utf-8");
			globalPresets = JSON.parse(content);
		} catch (err) {
			console.error(`Failed to load global presets from ${globalPath}: ${err}`);
		}
	}

	// Load project presets
	if (existsSync(projectPath)) {
		try {
			const content = readFileSync(projectPath, "utf-8");
			projectPresets = JSON.parse(content);
		} catch (err) {
			console.error(`Failed to load project presets from ${projectPath}: ${err}`);
		}
	}

	// Merge (project overrides global)
	return { ...globalPresets, ...projectPresets };
}

export default function presetExtension(pi: ExtensionAPI) {
	let presets: PresetsConfig = {};
	let activePresetName: string | undefined;
	let activePreset: Preset | undefined;

	// Register --preset CLI flag
	pi.registerFlag("preset", {
		description: "Preset configuration to use",
		type: "string",
	});

	/**
	 * Apply a preset configuration.
	 */
	async function applyPreset(name: string, preset: Preset, ctx: ExtensionContext): Promise<boolean> {
		// Apply model if specified
		if (preset.provider && preset.model) {
			const model = ctx.modelRegistry.find(preset.provider, preset.model);
			if (model) {
				const success = await pi.setModel(model);
				if (!success) {
					ctx.ui.notify(`Preset "${name}": No API key for ${preset.provider}/${preset.model}`, "warning");
				}
			} else {
				ctx.ui.notify(`Preset "${name}": Model ${preset.provider}/${preset.model} not found`, "warning");
			}
		}

		// Apply thinking level if specified
		if (preset.thinkingLevel) {
			pi.setThinkingLevel(preset.thinkingLevel);
		}

		// Apply tools if specified
		if (preset.tools && preset.tools.length > 0) {
			const allToolNames = pi.getAllTools().map((t) => t.name);
			const validTools = preset.tools.filter((t) => allToolNames.includes(t));
			const invalidTools = preset.tools.filter((t) => !allToolNames.includes(t));

			if (invalidTools.length > 0) {
				ctx.ui.notify(`Preset "${name}": Unknown tools: ${invalidTools.join(", ")}`, "warning");
			}

			if (validTools.length > 0) {
				pi.setActiveTools(validTools);
			}
		}

		// Store active preset for system prompt injection
		activePresetName = name;
		activePreset = preset;

		return true;
	}

	/**
	 * Build description string for a preset.
	 */
	function buildPresetDescription(preset: Preset): string {
		const parts: string[] = [];

		if (preset.provider && preset.model) {
			parts.push(`${preset.provider}/${preset.model}`);
		}
		if (preset.thinkingLevel) {
			parts.push(`thinking:${preset.thinkingLevel}`);
		}
		if (preset.tools) {
			parts.push(`tools:${preset.tools.join(",")}`);
		}
		if (preset.instructions) {
			const truncated =
				preset.instructions.length > 30 ? `${preset.instructions.slice(0, 27)}...` : preset.instructions;
			parts.push(`"${truncated}"`);
		}

		return parts.join(" | ");
	}

	/**
	 * Show preset selector UI using custom SelectList component.
	 */
	async function showPresetSelector(ctx: ExtensionContext): Promise<void> {
		const presetNames = Object.keys(presets);

		if (presetNames.length === 0) {
			ctx.ui.notify("No presets defined. Add presets to ~/.pi/agent/presets.json or .pi/presets.json", "warning");
			return;
		}

		// Build select items with descriptions
		const items: SelectItem[] = presetNames.map((name) => {
			const preset = presets[name];
			const isActive = name === activePresetName;
			return {
				value: name,
				label: isActive ? `${name} (active)` : name,
				description: buildPresetDescription(preset),
			};
		});

		// Add "None" option to clear preset
		items.push({
			value: "(none)",
			label: "(none)",
			description: "Clear active preset, restore defaults",
		});

		const result = await ctx.ui.custom<string | null>((tui, theme, _kb, done) => {
			const container = new Container();
			container.addChild(new DynamicBorder((str) => theme.fg("accent", str)));

			// Header
			container.addChild(new Text(theme.fg("accent", theme.bold("Select Preset"))));

			// SelectList with themed styling
			const selectList = new SelectList(items, Math.min(items.length, 10), {
				selectedPrefix: (text) => theme.fg("accent", text),
				selectedText: (text) => theme.fg("accent", text),
				description: (text) => theme.fg("muted", text),
				scrollInfo: (text) => theme.fg("dim", text),
				noMatch: (text) => theme.fg("warning", text),
			});

			selectList.onSelect = (item) => done(item.value);
			selectList.onCancel = () => done(null);

			container.addChild(selectList);

			// Footer hint
			container.addChild(new Text(theme.fg("dim", "↑↓ navigate • enter select • esc cancel")));

			container.addChild(new DynamicBorder((str) => theme.fg("accent", str)));

			return {
				render(width: number) {
					return container.render(width);
				},
				invalidate() {
					container.invalidate();
				},
				handleInput(data: string) {
					selectList.handleInput(data);
					tui.requestRender();
				},
			};
		});

		if (!result) return;

		if (result === "(none)") {
			// Clear preset and restore defaults
			activePresetName = undefined;
			activePreset = undefined;
			pi.setActiveTools(["read", "bash", "edit", "write"]);
			ctx.ui.notify("Preset cleared, defaults restored", "info");
			updateStatus(ctx);
			return;
		}

		const preset = presets[result];
		if (preset) {
			await applyPreset(result, preset, ctx);
			ctx.ui.notify(`Preset "${result}" activated`, "info");
			updateStatus(ctx);
		}
	}

	/**
	 * Update status indicator.
	 */
	function updateStatus(ctx: ExtensionContext) {
		if (activePresetName) {
			ctx.ui.setStatus("preset", ctx.ui.theme.fg("accent", `preset:${activePresetName}`));
		} else {
			ctx.ui.setStatus("preset", undefined);
		}
	}

	function getPresetOrder(): string[] {
		return Object.keys(presets).sort();
	}

	async function cyclePreset(ctx: ExtensionContext): Promise<void> {
		const presetNames = getPresetOrder();
		if (presetNames.length === 0) {
			ctx.ui.notify("No presets defined. Add presets to ~/.pi/agent/presets.json or .pi/presets.json", "warning");
			return;
		}

		const cycleList = ["(none)", ...presetNames];
		const currentName = activePresetName ?? "(none)";
		const currentIndex = cycleList.indexOf(currentName);
		const nextIndex = currentIndex === -1 ? 0 : (currentIndex + 1) % cycleList.length;
		const nextName = cycleList[nextIndex];

		if (nextName === "(none)") {
			activePresetName = undefined;
			activePreset = undefined;
			pi.setActiveTools(["read", "bash", "edit", "write"]);
			ctx.ui.notify("Preset cleared, defaults restored", "info");
			updateStatus(ctx);
			return;
		}

		const preset = presets[nextName];
		if (!preset) return;

		await applyPreset(nextName, preset, ctx);
		ctx.ui.notify(`Preset "${nextName}" activated`, "info");
		updateStatus(ctx);
	}

	pi.registerShortcut(Key.ctrlShift("u"), {
		description: "Cycle presets",
		handler: async (ctx) => {
			await cyclePreset(ctx);
		},
	});

	// Register /preset command
	pi.registerCommand("preset", {
		description: "Switch preset configuration",
		handler: async (args, ctx) => {
			// If preset name provided, apply directly
			if (args?.trim()) {
				const name = args.trim();
				const preset = presets[name];

				if (!preset) {
					const available = Object.keys(presets).join(", ") || "(none defined)";
					ctx.ui.notify(`Unknown preset "${name}". Available: ${available}`, "error");
					return;
				}

				await applyPreset(name, preset, ctx);
				ctx.ui.notify(`Preset "${name}" activated`, "info");
				updateStatus(ctx);
				return;
			}

			// Otherwise show selector
			await showPresetSelector(ctx);
		},
	});

	// Inject preset instructions into system prompt
	pi.on("before_agent_start", async (event) => {
		if (activePreset?.instructions) {
			return {
				systemPrompt: `${event.systemPrompt}\n\n${activePreset.instructions}`,
			};
		}
	});

	// Initialize on session start
	pi.on("session_start", async (_event, ctx) => {
		// Load presets from config files
		presets = loadPresets(ctx.cwd);

		// Check for --preset flag
		const presetFlag = pi.getFlag("preset");
		if (typeof presetFlag === "string" && presetFlag) {
			const preset = presets[presetFlag];
			if (preset) {
				await applyPreset(presetFlag, preset, ctx);
				ctx.ui.notify(`Preset "${presetFlag}" activated`, "info");
			} else {
				const available = Object.keys(presets).join(", ") || "(none defined)";
				ctx.ui.notify(`Unknown preset "${presetFlag}". Available: ${available}`, "warning");
			}
		}

		// Restore preset from session state
		const entries = ctx.sessionManager.getEntries();
		const presetEntry = entries
			.filter((e: { type: string; customType?: string }) => e.type === "custom" && e.customType === "preset-state")
			.pop() as { data?: { name: string } } | undefined;

		if (presetEntry?.data?.name && !presetFlag) {
			const preset = presets[presetEntry.data.name];
			if (preset) {
				activePresetName = presetEntry.data.name;
				activePreset = preset;
				// Don't re-apply model/tools on restore, just keep the name for instructions
			}
		}

		updateStatus(ctx);
	});

	// Persist preset state
	pi.on("turn_start", async () => {
		if (activePresetName) {
			pi.appendEntry("preset-state", { name: activePresetName });
		}
	});
}

// ─── GET /api/pipeline/runs/:runId — Get run detail + story results ──────────

/**
 * @swagger
 * /api/pipeline/runs/{runId}:
 *   get:
 *     tags: [Pipeline]
 *     summary: Get a pipeline run with story results
 *     operationId: getPipelineRun
 *     x-rorca-tier: public
 *     x-rorca-rationale: "Detailed run state is core read-only execution data for CLI reattachment, monitoring, and MCP usage."
 *     x-rorca-public-api: true
 *     description: Retrieves a single pipeline run by ID along with all its story results and spec metadata.
 *     parameters:
 *       - in: path
 *         name: runId
 *         required: true
 *         schema: { type: integer }
 *     responses:
 *       200:
 *         description: Run details with story results
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 run: { $ref: '#/components/schemas/PipelineRun' }
 *                 stories:
 *                   type: array
 *                   items: { $ref: '#/components/schemas/StoryResult' }
 *                 worktreePath: { type: string, nullable: true, description: "Worktree path (if run uses worktree isolation)" }
 *                 branchName: { type: string, nullable: true, description: "Git branch name (if run uses worktree isolation)" }
 *       404: { description: "Run not found" }
 */
router.get('/runs/:runId', async (req: Request, res: Response) => {
  try {
    const runId = parseInt(String(req.params.runId), 10);
    if (isNaN(runId)) {
      throw new ValidationError('Invalid runId');
      return;
    }

    const run = await queryOne('SELECT * FROM pipeline_runs WHERE id = $1', [runId]) as PipelineRunRow | undefined;

    if (!run) {
      throw new NotFoundError('Run not found');
      return;
    }

    const stories = await query('SELECT * FROM story_results WHERE run_id = $1 ORDER BY id ASC', [runId]) as StoryResultRow[];

    // Read spec JSON to return full userStories list (including pending ones)
    // OC-029: Include per-story engine assignment in response
    const runAgentType = (run.agent_type || run.agent || 'claude') as AgentType;
    let specStories: { id: string; title: string; dependsOn?: string[]; passes?: boolean; agent?: string; reroute?: { fromEngine: string; toEngine: string; reason: string } }[] = [];
    let specModel: string | null = null;
    try {
      const workspace = await queryOne('SELECT path FROM workspaces WHERE id = $1', [run.workspace_id]) as { path: string } | undefined;
      if (workspace) {
        const absSpecPath = path.join(workspace.path, run.spec_path);
        if (fs.existsSync(absSpecPath)) {
          const specJson = JSON.parse(fs.readFileSync(absSpecPath, 'utf-8'));
          specModel = specJson.model || null;
          if (Array.isArray(specJson.userStories)) {
            specStories = specJson.userStories.map((s: any) => {
              const storyAgent = resolveStoryAgent(s, runAgentType);
              const reroute = reroutedStories.get(s.id);
              return {
                id: s.id,
                title: s.title,
                dependsOn: s.dependsOn,
                passes: s.passes,
                agent: storyAgent,
                suggestedSkills: Array.isArray(s.suggestedSkills) ? s.suggestedSkills : [],
                ...(reroute ? { reroute: { fromEngine: reroute.fromEngine, toEngine: reroute.toEngine, reason: reroute.reason } } : {}),
              };
            });
          }
        }
      }
    } catch {
      // Spec file missing or malformed — specStories stays empty
    }

    // OC-029: Enrich specStories with reroute data from WAL events (for historical runs)
    if (specStories.length > 0) {
      try {
        const rerouteEvents = await query<{ story_id: string; payload: string }>(`SELECT story_id, payload FROM wal_events WHERE event_type = 'story_rerouted' AND (payload->>'run_id')::bigint = $1 ORDER BY id ASC`, [runId]);
        for (const evt of rerouteEvents) {
          const story = specStories.find(s => s.id === evt.story_id);
          if (story && !story.reroute) {
            try {
              const p = JSON.parse(evt.payload);
              story.reroute = { fromEngine: p.fromEngine, toEngine: p.toEngine, reason: p.reason };
            } catch { /* malformed payload */ }
          }
        }
      } catch { /* WAL query error — non-fatal */ }
    }

    // Aggregate token counts and cost from story_results
    const tokenRow = await queryOne(`SELECT COALESCE(SUM(input_tokens), 0) AS total_input,
              COALESCE(SUM(output_tokens), 0) AS total_output,
              COALESCE(SUM(cost_usd), 0) AS total_cost
       FROM story_results WHERE run_id = $1`, [runId]) as { total_input: number; total_output: number; total_cost: number };

    // Per-story token breakdown
    const storyTokenBreakdown = stories.map((s) => ({
      storyId: s.story_id,
      status: s.status,
      inputTokens: s.input_tokens ?? 0,
      outputTokens: s.output_tokens ?? 0,
      modelUsed: s.model_used ?? null,
      costUsd: s.cost_usd ?? 0,
    }));

    // CIE-007: Read run-state.json for real-time story progress fallback
    let runState: RunState | null = null;
    try {
      const workspace = await queryOne('SELECT path FROM workspaces WHERE id = $1', [run.workspace_id]) as { path: string } | undefined;
      if (workspace) {
        runState = readRunState(workspace.path);
        // Only include if it belongs to this run
        if (runState && runState.runId !== runId) runState = null;
      }
    } catch { /* non-fatal */ }

    // CIE-016: Build actual vs predicted context comparison
    let contextComparison: {
      predicted: Record<string, { totalTokens: number; injectedFiles: string[] }>;
      actual: Record<string, { contextFiles: string[] }>;
    } | null = null;

    const predictedRaw = (run as any).context_preview;
    if (predictedRaw) {
      try {
        const predicted = JSON.parse(predictedRaw);
        const predictedMap: Record<string, { totalTokens: number; injectedFiles: string[] }> = {};
        for (const s of (predicted.stories ?? [])) {
          predictedMap[s.storyId] = { totalTokens: s.totalTokens, injectedFiles: s.injectedFiles };
        }

        // Collect actual context_files from story_started WAL events
        const actualMap: Record<string, { contextFiles: string[] }> = {};
        try {
          const walRows = await query<{ story_id: string; payload: string }>(`SELECT story_id, payload FROM wal_events WHERE event_type = 'story_started' AND (payload->>'run_id')::bigint = $1`, [runId]);
          for (const row of walRows) {
            try {
              const p = JSON.parse(row.payload);
              if (p.context_files) {
                actualMap[row.story_id] = { contextFiles: p.context_files };
              }
            } catch { /* skip */ }
          }
        } catch { /* non-fatal */ }

        contextComparison = { predicted: predictedMap, actual: actualMap };
      } catch { /* malformed context_preview */ }
    }

    res.json({
      run,
      stories,
      specStories,
      specModel,
      agentType: run.agent_type || run.agent || 'claude',
      agentModel: run.agent_model || null,
      // US-004: Expose worktree fields at top level for easy frontend access
      worktreePath: run.worktree_path || null,
      branchName: run.branch_name || null,
      includeGraph: run.include_graph ?? false,
      tokenSummary: {
        inputTokens: tokenRow.total_input,
        outputTokens: tokenRow.total_output,
        totalCostUsd: tokenRow.total_cost,
      },
      storyTokenBreakdown,
      runState,
      contextComparison,
    });
  } catch (error: any) {
    handleRouteError(res, error, '[Pipeline] Get run');
  }
});

// ─── POST /api/pipeline/runs/:runId/retry — Retry failed stories ─────────────
// Accepts optional 'storyIds' array; when omitted, retries all failed stories.
// Preserves original failed story_result rows for audit trail.

/**
 * @swagger
 * /api/pipeline/runs/{runId}/retry:
 *   post:
 *     tags: [Pipeline]
 *     summary: Retry failed stories in a pipeline run via pg-boss job queue
 *     operationId: retryPipelineRun
 *     x-rorca-tier: public
 *     x-rorca-rationale: "Retrying failed local stories is part of the stable open-source execution workflow and has no billing or admin side effects."
 *     x-rorca-public-api: true
 *     description: Re-executes failed stories from a completed or partially failed pipeline run, optionally filtering to specific story IDs. Enqueues a pipeline:retry pg-boss job; worker handles the actual spawn.
 *     parameters:
 *       - in: path
 *         name: runId
 *         required: true
 *         schema: { type: integer }
 *     requestBody:
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             properties:
 *               storyIds:
